import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    book = {}  # id -> {'side','price','qty','seq','active'}
    seq_counter = 0

    def add_to_book(id_, side, price, qty, seq):
        book[id_] = {'side': side, 'price': price, 'qty': qty, 'seq': seq, 'active': True}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, id_))
        else:
            heapq.heappush(sell_heap, (price, seq, id_))

    def clean_buy():
        while buy_heap:
            negp, seq, id_ = buy_heap[0]
            o = book.get(id_)
            if o is None or not o['active'] or o['qty'] <= 0:
                heapq.heappop(buy_heap)
            else:
                break

    def clean_sell():
        while sell_heap:
            p, seq, id_ = sell_heap[0]
            o = book.get(id_)
            if o is None or not o['active'] or o['qty'] <= 0:
                heapq.heappop(sell_heap)
            else:
                break

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            id_ = order[1]
            o = book.get(id_)
            if o and o['active'] and o['qty'] > 0:
                o['active'] = False
            continue

        if typ == 'limit':
            _, id_, side, price, qty = order
        elif typ == 'ioc':
            _, id_, side, price, qty = order
        elif typ == 'market':
            _, id_, side, qty = order
            price = None
        else:
            continue

        remaining = qty
        seq_counter += 1
        my_seq = seq_counter

        if side == 'buy':
            while remaining > 0:
                clean_sell()
                if not sell_heap:
                    break
                p, s_seq, s_id = sell_heap[0]
                if typ != 'market' and p > price:
                    break
                sorder = book[s_id]
                trade_qty = min(remaining, sorder['qty'])
                trades.append([id_, s_id, p, trade_qty])
                remaining -= trade_qty
                sorder['qty'] -= trade_qty
                if sorder['qty'] == 0:
                    sorder['active'] = False
                    heapq.heappop(sell_heap)
            if remaining > 0 and typ == 'limit':
                add_to_book(id_, side, price, remaining, my_seq)
        else:  # sell
            while remaining > 0:
                clean_buy()
                if not buy_heap:
                    break
                negp, b_seq, b_id = buy_heap[0]
                p = -negp
                if typ != 'market' and p < price:
                    break
                border = book[b_id]
                trade_qty = min(remaining, border['qty'])
                trades.append([b_id, id_, p, trade_qty])
                remaining -= trade_qty
                border['qty'] -= trade_qty
                if border['qty'] == 0:
                    border['active'] = False
                    heapq.heappop(buy_heap)
            if remaining > 0 and typ == 'limit':
                add_to_book(id_, side, price, remaining, my_seq)

    return trades

